iniciarSesionWeb();
if (empty($_SESSION['usuario_id']) || ($_SESSION['tipo_cuenta'] ?? '') !== 'ADMIN') { header('Location: ' . rutaBasePublica() . '/index.php'); exit; }
$mesActual=(new DateTimeImmutable('now',new DateTimeZone('America/La_Paz')))->format('Y-m');
?>
<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Configuración | Restaurante Rumbo al Cielo</title><link rel="stylesheet" href="<?= escaparHtml(rutaBasePublica()) ?>/assets/css/app.css"></head>
<body class="pagina-panel"><main class="panel"><header class="panel-cabecera"><a class="marca marca-enlace" href="<?= escaparHtml(rutaBasePublica()) ?>/admin/dashboard.php"><img src="<?= escaparHtml(rutaBasePublica()) ?>/assets/img/uab-favicon.png" alt=""><span><strong>Rumbo al Cielo</strong><small>ADMINISTRACIÓN</small></span></a><a class="boton-secundario" href="<?= escaparHtml(rutaBasePublica()) ?>/admin/dashboard.php">Volver al inicio</a></header>
<section class="panel-contenido panel-contenido-ancho"><span class="etiqueta etiqueta-verde">REGLAS DEL RESTAURANTE</span><h1>Parámetros del sistema</h1><p>Los cambios de tarifa, mínimo y horario se aplican a las reservas y a los reportes que se generen después.</p>
<form id="form-configuracion" class="formulario-empleado"><div class="campo-formulario"><label for="tarifa_pensionado">Tarifa mensual (Bs)</label><input id="tarifa_pensionado" name="tarifa_pensionado" type="number" min="0" max="999999.99" step="0.01" required></div><div class="campo-formulario"><label for="tarifa_esporadico">Tarifa esporádica (Bs)</label><input id="tarifa_esporadico" name="tarifa_esporadico" type="number" min="0" max="999999.99" step="0.01" required></div><div class="campo-formulario"><label for="minimo_almuerzos_mes">Mínimo mensual</label><input id="minimo_almuerzos_mes" name="minimo_almuerzos_mes" type="number" min="0" max="31" step="1" required></div><div class="campo-formulario"><label for="hora_limite">Hora límite</label><input id="hora_limite" name="hora_limite" type="time" required></div><button class="boton-formulario" type="submit">Guardar parámetros</button></form>
<p class="mensaje" id="mensaje-config" role="status" aria-live="polite"></p><hr>
<h2>Calendario operativo</h2><p>Registra un feriado o quita esa condición marcando la fecha como día operativo.</p>
<form id="form-dia" class="formulario-empleado"><div class="campo-formulario"><label for="fecha-dia">Fecha</label><input id="fecha-dia" name="fecha" type="date" required></div><div class="campo-formulario"><label for="es_feriado">Tipo de día</label><select id="es_feriado" name="es_feriado"><option value="true">Feriado</option><option value="false">Día operativo</option></select></div><div class="campo-formulario"><label for="descripcion">Descripción del feriado</label><input id="descripcion" name="descripcion" maxlength="200" placeholder="Ej. Día de la Independencia"></div><button class="boton-formulario" type="submit">Guardar fecha</button></form>
<div class="campo-formulario" style="margin-top:28px"><label for="mes-calendario">Ver calendario del mes</label><input id="mes-calendario" type="month" value="<?= escaparHtml($mesActual) ?>"></div><div id="lista-calendario" class="lista-reservas">Cargando fechas…</div></section></main>
<script>
const configForm=document.querySelector('#form-configuracion');const configMessage=document.querySelector('#mensaje-config');const dayForm=document.querySelector('#form-dia');const monthInput=document.querySelector('#mes-calendario');const calendarList=document.querySelector('#lista-calendario');
function notice(el,text,ok){el.textContent=text;el.className=`mensaje ${ok?'mensaje-exito':'mensaje-error'}`;}
async function json(url,options){const res=await fetch(url,options);const data=await res.json();if(!res.ok||!data.exito)throw new Error(data.mensaje||'No se pudo completar la solicitud.');return data;}
async function cargarConfig(){const data=await json('../api/configuracion.php');for(const [key,value] of Object.entries(data.configuracion)){configForm.elements[key].value=value;}}
async function cargarCalendario(){const data=await json(`../api/configuracion.php?accion=calendario&periodo=${encodeURIComponent(monthInput.value)}`);if(!data.dias.length){calendarList.textContent='No hay fechas registradas para este mes.';return;}const tabla=document.createElement('table');tabla.className='tabla-reservas';const head=document.createElement('thead');const hr=document.createElement('tr');for(const title of ['Fecha','Tipo','Descripción']){const th=document.createElement('th');th.textContent=title;hr.append(th);}head.append(hr);const body=document.createElement('tbody');for(const day of data.dias){const tr=document.createElement('tr');for(const value of [day.fecha,Number(day.es_feriado)?'Feriado':'Día operativo',day.descripcion_feriado||'—']){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);}tabla.append(head,body);calendarList.replaceChildren(tabla);}
configForm.addEventListener('submit',async(e)=>{e.preventDefault();const body=new FormData(configForm);body.set('accion','actualizar');try{const data=await json('../api/configuracion.php',{method:'POST',body});notice(configMessage,data.mensaje,true);}catch(err){notice(configMessage,err.message,false);}});
dayForm.addEventListener('submit',async(e)=>{e.preventDefault();const body=new FormData(dayForm);body.set('accion','guardar_dia');try{const data=await json('../api/configuracion.php',{method:'POST',body});notice(configMessage,data.mensaje,true);await cargarCalendario();}catch(err){notice(configMessage,err.message,false);}});
monthInput.addEventListener('change',()=>cargarCalendario().catch(err=>{calendarList.textContent=err.message;}));
Promise.all([cargarConfig(),cargarCalendario()]).catch(err=>notice(configMessage,err.message,false));
</script></body></html>
